// ---------------------------------------------------------------------------
// THE VALIDATION GATE (PLAN 7.2 / W2 note).
// Six downstream workflows read these rows. A malformed scene here fails
// silently three stages later, after you have already paid for voice and
// images. So: reject here, loudly, before anything is written.
// ---------------------------------------------------------------------------
const job = $('Claim Job').first().json;
const raw = $input.first().json?.choices?.[0]?.message?.content;

if (!raw) throw new Error('Model returned no content');

let parsed;
try {
  parsed = JSON.parse(raw);
} catch (e) {
  throw new Error('Invalid JSON from model: ' + String(raw).slice(0, 300));
}

const scenes = parsed.scenes;
if (!Array.isArray(scenes) || scenes.length < 3) {
  throw new Error('Expected at least 3 scenes, got ' + (scenes ? scenes.length : 'none'));
}
if (scenes.length > 20) {
  throw new Error('Refusing ' + scenes.length + ' scenes — cost guard (max 20)');
}

const problems = [];
const rows = scenes.map((s, i) => {
  const n = i + 1;

  if (!s.narration || !String(s.narration).trim()) problems.push('scene ' + n + ': empty narration');
  if (!s.image_prompt || !String(s.image_prompt).trim()) problems.push('scene ' + n + ': empty image_prompt');

  const words = String(s.narration || '').trim().split(/\s+/).filter(Boolean).length;
  // 12-20 is the instruction; allow 10-24 before rejecting outright.
  if (words < 10 || words > 24) {
    problems.push('scene ' + n + ': narration is ' + words + ' words (need 10-24)');
  }

  // Style consistency is enforced HERE, mechanically — not left to the model
  // remembering to do it on every scene (PLAN 7.3).
  const suffix = job.style_suffix ? ', ' + job.style_suffix : '';

  return {
    job_id:         job.id,
    scene_number:   n,
    narration:      String(s.narration || '').trim(),
    image_prompt:   String(s.image_prompt || '').trim() + suffix,
    motion_prompt:  String(s.motion_prompt || 'slow push in').trim(),
    on_screen_text: String(s.on_screen_text || '').trim().slice(0, 60),
    status:         'pending'
  };
});

if (problems.length) {
  throw new Error('Script rejected — ' + problems.join('; '));
}

return [{
  json: {
    job_id: job.id,
    title:  parsed.title ? String(parsed.title).slice(0, 200) : job.title,
    script: parsed,
    scenes: rows,
    scene_count: rows.length
  }
}];
